window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["32"]={"https://theconversation.com/after-the-referendum-whats-next-for-premier-danielle-smith-and-her-united-conservative-party-296036":{"r":"conversation","at":"2026-11-17T16:30Z","sha":"a631b3b5a36cd94569a589e409054d2dac40d31cc3fb64823abd51d3198c7b9c","read":"https://theconversation.com/after-the-referendum-whats-next-for-premier-danielle-smith-and-her-united-conservative-party-296036","bytes":186374,"x":"fulltext v1","title":"After the referendum: What’s next for Premier Danielle Smith and her United Conservative Party?","by":[{"n":"Donald Barry","r":"Professor Emeritus, Political Science, University of Calgary"}],"pub":"2026-11-09T15:08:14Z","mod":"","blocks":[{"k":"p","s":["As expected, Albertans ",["voted overwhelmingly in favour","https://theconversation.com/albertans-soundly-vote-to-stay-in-canada-many-are-asking-why-they-had-to-vote-in-the-first-place-294396"]," of remaining in Canada in the province’s recent independence referendum."]},{"k":"p","s":["While attention focused on the independence issue, nine other questions covering immigration and constitutional change topped the Alberta government’s agenda. ",["Close wins on the immigration questions and the defeat of those on constitutional change","https://www.elections.ab.ca/resources/media/news-releases/2026-10-29-2/"]," have left Premier Danielle Smith struggling with how to proceed."]},{"k":"p","s":["In February, Smith announced a referendum on the nine questions, based on recommendations of a government-sponsored ",["Alberta Next panel","https://www.alberta.ca/alberta-next-panel-engagement"],". The panel held town hall meetings across the province in 2025 to explore ways to increase Alberta’s autonomy."]},{"k":"h","s":["The nature of the questions"]},{"k":"p","s":["Five questions asked whether Alberta should take more control over immigration, limit or impose residency requirements for non-permanent residents seeking social supports, charge fees for access to health care and education and require proof of citizenship to vote in provincial elections."]},{"k":"p","s":["Four questions asked whether Alberta should work with other provinces for constitutional amendments to let provinces appoint Superior Court judges, abolish the Senate, opt out of federal programs without losing funding and give provincial laws priority over federal laws in areas of shared jurisdiction."]},{"k":"p","s":["Left out were the creation of an Alberta pension plan, a tax collection agency and a provincial police force, which polls showed lacked public backing."]},{"k":"p","s":["“We’ve done that initial culling of the questions to make sure that we found the ones that are likely to get majority support,” ",["Smith said","https://www.cbc.ca/news/canada/calgary/analysis-danielle-smith-nine-alberta-referendum-questions-immigration-constitutional-9.7379412"],"."]},{"k":"p","s":["Her government also launched a $4 million ad campaign urging Albertans to vote yes to the questions."]},{"k":"h","s":["Urban/rural divide except on separation"]},{"k":"p","s":["The ",["five immigration questions","https://officialresults.elections.ab.ca/orEDResultsReferendum2026.cfm?EventId=202610"]," narrowly passed, led by proof of citizenship in voting, with rural voters making up the majority of those who cast their ballots in favour of those measures. The four constitutional questions were defeated."]},{"k":"p","s":["Voters in Calgary and Edmonton, the province’s two largest cities where more than half of the province’s population resides, opposed all nine questions, the only exception being proof of citizenship to vote, which prevailed in Calgary."]},{"k":"p","s":[["Smith observed","https://www.ctvnews.ca/edmonton/article/more-constitutional-referendum-questions-flip-to-no-as-elections-alberta-keeps-counting-past-deadline/"],": “We have to focus on the things that Albertans want us focusing on.” She says the government will ",["“proceed with caution”","https://www.theglobeandmail.com/canada/alberta/article-repercussions-alberta-referendum-immigration-question-ucp-danielle/"]," on immigration."]},{"k":"p","s":["But the prospect of action on immigration has alarmed the business and immigrant communities, and ",["prompted some United Conservative Party (UCP) members to leave the party","https://www.politt.ca/news/ucp-members-quit-business-leaders-warn-as-albertas-immigration-referendum-sparks-backlash/"],". None of the immigration questions are on the government’s fall legislative agenda."]},{"k":"h","s":["‘No’ to independence"]},{"k":"p","s":["The independence question, which asked people whether they wanted to stay in Canada or move towards a binding referendum on separation, was added in May to keep Smith’s divided party together ",["after separatists in the party launched a citizen petition calling for a vote on independence. More than half of the party’s members are separatist supporters.","https://www.cbc.ca/news/canada/the-alberta-question-9.7371294"]]},{"k":"p","s":["Smith said she would vote to remain after she and Prime Minister Mark Carney announced a climate and energy pact that would facilitate a West Coast pipeline to transport Alberta oil to Asian markets — ",["a move she said shows federalism can work","https://www.cbc.ca/news/politics/carney-smith-energy-announcement-mou-9.7200652"],"."]},{"k":"p","s":["Read more: ",["Albertans disapprove of Donald Trump — and his brand is weakening separatism, too","https://theconversation.com/albertans-disapprove-of-donald-trump-and-his-brand-is-weakening-separatism-too-292573"]]},{"k":"p","s":["Some ",["75 per cent of Albertans","https://officialresults.elections.ab.ca/orEDResultsReferendum2026.cfm?EventId=202610"],", led by voters in Calgary and Edmonton with smaller majorities elsewhere, supported staying in Canada. Two rural ridings held by the UCP voted for separation."]},{"k":"p","s":["Smith says ",["separatists must accept the results of the vote or leave the party, adding there will not be another independence referendum on her watch","https://calgaryherald.com/opinion/columnists/bell-danielle-smiths-ultimatum-to-ucp-separatists-toe-the-party-line-or-leave"],". The decisive remain victory appears to have defused a challenge to her leadership from pro-independence members at the party’s next annual meeting in November, ",["but separatist sentiment remains","https://thetyee.ca/Analysis/2026/10/29/Separatism-Alberta-Not-Done/"],"."]},{"k":"h","s":["The NDP’s popularity"]},{"k":"p","s":["The referendum vote has highlighted the ",["sharp divide","https://www.cbc.ca/news/canada/calgary/danielle-smith-referendum-edmonton-calgary-9.7399988"]," between urban Calgary and Edmonton and other parts of the province that form the UCP’s base."]},{"k":"p","s":["Smith’s government has not hesitated to involve itself in local issues in Calgary and Edmonton, ranging from education to housing, transit, bike lanes and library books, while ",["downloading the costs of municipal services","https://www.cbc.ca/news/canada/calgary/one-billion-downloaded-costs-9.7222266"]," onto local governments."]},{"k":"p","s":[["Smith has seen her popularity plummet to a record low in recent months","https://www.ctvnews.ca/calgary/article/danielle-smiths-approval-rating-drops-to-new-low-angus-reid"]," and is facing an election in October 2027. She has ",["belatedly recognized","https://calgaryherald.com/opinion/columnists/bell-no-fighting-danielle-smith-offers-olive-branch-calgary-edmonton"]," that her government needs to appeal to voters in Calgary and Edmonton to maintain its grip on power. The New Democrats, led by former Calgary mayor Naheed Nenshi, hold most of the seats in Calgary and all of them in Edmonton."]},{"k":"p","s":["Smith’s government, its revenue bolstered by high oil prices, has begun to respond, announcing a modest reduction in municipal ",["education property tax rates","https://globalnews.ca/news/12128097/alberta-education-property-taxes/"]," that it had increased dramatically in recent years."]},{"k":"p","s":["The premier has ",["upped her attacks","https://www.bing.com/videos/riverview/relatedvideo?q=Danielle+Smith+attacks+NDP+on+Power+and+Politics&mid=A81D7FBC4066D8E57000A81D7FBC4066D8E57000&churl=&mmscn=stvo&FORM=VIRE"]," on the surging NDP, which ",["is even","https://www.mainstreetresearch.ca/post/alberta-decides"]," with the UCP in the polls and won a recent byelection in a Calgary riding previously held by Smith’s party."]},{"k":"p","s":["Smith has urged her party to unite to prevent the NDP from winning next year’s election, claiming it is ",["under the thumb","https://calgaryherald.com/news/politics/naheed-nenshi-critical-federal-ndp-avi-lewis-leadership-victory"]," of its federal counterpart headed by fossil fuel opponent Avi Lewis — even though the Alberta NDP has severed membership ties with the national party and supports oil and gas development."]},{"k":"h","s":["Riding redistribution"]},{"k":"p","s":["Smith’s government has caused another controversy with the newly released report of the ",["Independent Advisory Panel on Electoral Boundaries,","https://www.assembly.ab.ca/docs/default-source/committees/ceb/8.5x11_iapreport_digital_oct19_lowres.pdf?sfvrsn=3774d9bb_14"]," which ",["favours the UCP","https://www.cbc.ca/news/canada/calgary/alberta-riding-electoral-boundaries-data-analysis-danielle-smith-naheed-nenshi-9.7409182"]," in its proposed American-style riding distribution efforts."]},{"k":"p","s":["The panel was created after the government, in an unprecedented move, rejected the report of the officially appointed ",["Alberta Electoral Boundaries Commission","https://www.elections.ab.ca/uploads/abebc_2026_rpt_final.pdf"]," earlier this year. That report, which was endorsed by the commission chair (a judge), and two members named by the NDP, was challenged by its two government-appointed members, who offered a highly partisan report of their own."]},{"k":"p","s":["The Advisory Panel’s findings are supported by the chair (a retired judge) and two government-named members, with two NDP appointees opposed."]},{"k":"p","s":["The panel’s proposed electoral map, drawn up without public consultation, adds two rural seats and transforms three constituencies in Calgary and three in Lethbridge into hybrid ridings that stretch from those cities into the surrounding rural areas, which are populated with reliably UCP voters."]},{"k":"p","s":["The government ",["has rejected","https://www.cbc.ca/news/canada/edmonton/elections-alberta-mickey-amery-9.7405056"]," the province’s chief elections officer’s request to delay implementation of the new map or postpone next year’s election to give the agency enough time to prepare. The report, which is expected to be adopted, is certain to be challenged in the courts."]},{"k":"p","s":["The stakes are high for Smith. Whether she and her government can successfully navigate the challenges facing them remains to be seen."]}],"chars":6787},"https://www.gov.uk/foreign-travel-advice/algeria":{"r":"govuk","at":"2026-11-17T16:38Z","sha":"583ba7b3679e1104cf9777a26891ca08ecddc16a111e14101fc84f97f98f691b","read":"https://www.gov.uk/api/content/foreign-travel-advice/algeria","bytes":66006,"x":"fulltext v1","title":"Algeria travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-19T00:00:00+00:00","mod":"2026-09-25T16:01:59+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Algeria border areas"]},{"k":"p","s":["FCDO advises against all travel to within 30km of Algeria’s borders with:"]},{"k":"li","s":["Libya"]},{"k":"li","s":["Mauritania"]},{"k":"li","s":["Mali"]},{"k":"li","s":["Niger"]},{"k":"li","s":["Tunisia – in the provinces of Illizi and Ouargla and in the Chaambi mountains area"]},{"k":"hs","s":["Rest of the Algeria-Tunisia border"]},{"k":"p","s":["FCDO advises against all but essential travel to within 30km of the rest of Algeria’s border with Tunisia."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/algeria/safety-and-security"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and get appropriate travel insurance. Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/algeria/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Algeria’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Algeria set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Algerian Consulate in the UK","https://www.algerian-consulate.org.uk/"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Algeria, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"hs","s":["If your passport is lost or stolen in Algeria"]},{"k":"p","s":["If your passport is lost or stolen during your stay, the Algerian authorities will ask for a police report when you leave the country."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Algeria."]},{"k":"p","s":["Check your visa details, including validity dates, before you travel. If you overstay, it is likely Algerian immigration police will detain you at the airport on departure. You may face criminal prosecution and up to 3 months in prison."]},{"k":"p","s":["If you want to extend your stay in Algeria, apply at the town hall (‘la wilaya’) nearest to you."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["Before you travel, apply for a visa through the ",["Algerian Consulate in the UK","https://www.algerian-consulate.org.uk/"],"."]},{"k":"p","s":["You may be able to get a tourist visa on arrival at some airports in Algeria if the majority of your travel is in the south of the country. You should have a confirmed reservation with an approved local travel agency. Contact the ",["Algerian Consulate in the UK","https://www.algerian-consulate.org.uk/"]," for more information and for details of approved travel agencies."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Algeria, you must have a certificate to prove you’ve had a yellow fever vaccination if you’re coming from a ",["country listed as a transmission risk","https://nathnacyfzone.org.uk/factsheet/65/countries-with-risk-of-yellow-fever-transmission"],"."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Algeria guide","https://travelhealthpro.org.uk/country/3/algeria#Vaccine_Recommendations"],"."]},{"k":"h","s":["Travelling with children"]},{"k":"p","s":["In Algeria, a child is:"]},{"k":"li","s":["someone under the age of 19 years and one day"]},{"k":"li","s":["considered to be an Algerian citizen if one of their parents is Algerian"]},{"k":"p","s":["If an Algerian citizen or a British-Algerian dual national child travels with one parent, the parent (whether mother or father) must prove their parental link through a ‘Livret de famille’ (original or certified copy)."]},{"k":"p","s":["Algerian children travelling alone must have a letter (‘Autorisation Parentale’) from their parent or legal guardian giving them permission to leave the country. Children not from Algeria travelling alone need to show proof of permanent residence in the country they are travelling to."]},{"k":"p","s":["For further information, check the website of the ",["Algerian Ministry of Interior","https://www.interieur.gov.dz/index.php/fr/mes-d%C3%A9marches-administratives/sortie-des-mineurs-%C3%A0-l-%C3%A9tranger.html"]," or contact the ",["Algerian Consulate in London","https://www.algerian-consulate.org.uk/"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into and out of Algeria","https://www.douane.gov.dz/?lang=en"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Souvenirs"]},{"k":"p","s":["You can get a prison sentence for smuggling antiquities in Algeria. If you buy souvenirs, get proof of authenticity for anything that looks old or antique. Otherwise, the Algerian authorities may detain you on departure at the airport and confiscate the souvenirs."]},{"k":"hs","s":["Taking money into and out of Algeria"]},{"k":"p","s":["Declare cash at your point of entry and exit into Algeria if the amount you are carrying exceeds 5000 euros or its equivalent in other currencies. Failure to declare or false declaration of imported and exported cash constitutes an offense which may lead to criminal prosecution."]},{"k":"p","s":["Only travellers with residency status are allowed to bring in and take out Algerian banknotes, up to a maximum of 10,000 Algerian dinars."]},{"k":"p","s":["For further details, see ",["You arrive in Algeria - Direction Générale des Douanes","https://www.douane.gov.dz/spip.php?article1&lang=fr"],"."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Algeria"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Algeria."]},{"k":"p","s":["Terrorist attacks could be indiscriminate, including in places visited by foreign nationals, such as:"]},{"k":"li","s":["transport hubs"]},{"k":"li","s":["locations popular with tourists and foreigners"]},{"k":"li","s":["government buildings"]},{"k":"li","s":["crowded places"]},{"k":"li","s":["businesses with western interests"]},{"k":"p","s":["There is also a risk that lone actors target foreign nationals. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"p","s":["The threat from terrorism is higher in some parts of the country, including:"]},{"k":"li","s":["the southern border, where the kidnap risk is concentrated"]},{"k":"li","s":["the Libyan and Tunisian borders"]},{"k":"li","s":["rural, and in particular mountainous, areas in the north and between Tunisia and Algiers"]},{"k":"li","s":["the Sahara"]},{"k":"p","s":["The terrorist threat comes from individuals inspired by Islamist extremist and anti-Semitic ideology and established groups, such as Al-Qaida in the Islamic Maghreb (AQIM). These groups have been active across the country and likely consider Western nationals legitimate targets."]},{"k":"p","s":["The Algerian authorities conduct effective counter-terrorism operations and retain a strong, visible security presence across the country."]},{"k":"hs","s":["Terrorist kidnap"]},{"k":"p","s":["There is a threat of kidnapping by groups operating in North Africa, particularly from Libya, Mauritania and groups originating in the Sahel. This includes AQIM and Daesh-affiliated groups, who may travel across the region’s porous border. There is a heightened risk of kidnap in border and remote desert areas of North Africa, particularly in the southern and eastern border areas (bordering Mali and Libya respectively). Terrorist groups have kidnapped foreigners, government officials and civilians in the region for financial gain and for political leverage."]},{"k":"p","s":["British nationals are seen as legitimate targets, including tourists, humanitarian aid workers, journalists and business travellers. If you are kidnapped, the reason for your presence is unlikely to protect you or secure your safe release."]},{"k":"p","s":["The long-standing policy of the British government is to not make substantive concessions to hostage takers. The British government considers that paying ransoms and releasing prisoners increases the risk of further hostage taking. The Terrorism Act (2000) also makes payments to terrorists illegal."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Algeria has a visible security presence across the country that gives considerable attention to the safety of its visitors. Demonstrations and other forms of protest are subject to various restrictions. You should take precautions for your personal safety by avoiding political gatherings and demonstrations. Follow instructions given by local security authorities."]},{"k":"h","s":["Algeria-Morocco border"]},{"k":"p","s":["The land border between Algeria and Morocco is closed. Do not attempt to cross it."]},{"k":"h","s":["Risk of arrest and detention"]},{"k":"p","s":["The Algerian authorities do not always inform the British Embassy when British nationals have been arrested. If you are detained, insist on your right to contact the British Embassy."]},{"k":"p","s":["It can take time for the British Embassy to get the necessary permission to visit you."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["There is a risk of pickpocketing, robbery and petty theft in the larger cities in Algeria."]},{"k":"p","s":["You can take precautions such as:"]},{"k":"li","s":["avoiding areas that you do not know, especially after dark in the suburbs"]},{"k":"li","s":["not carrying large amounts of money or valuables"]},{"k":"li","s":["not accepting lifts from people you do not know – use a taxi service recommended by your hotel"]},{"k":"p","s":["Maintain at least the same level of personal security awareness as in the UK and take care when walking or travelling alone."]},{"k":"p","s":["If you plan to tour the Casbah area of Algiers, use a good local guide and make sure your hosts or hotel know your plans."]},{"k":"p","s":["You should check the latest guidance of local authorities before moving around the country."]},{"k":"hs","s":["Security escorts"]},{"k":"p","s":["The Algerian authorities devote considerable resources to the safety of foreign visitors. There’s a clear security presence, which can feel intrusive."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["You will need your passport to check in to any hotels in Algeria. You do not have to carry your passport at all times, but take it with you on longer journeys. You must have your passport if you travel inside Algeria by air. Keep copies of your passport’s photo page and your visa or entry stamp in a separate place."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims. The dates vary by year and country, next starting in February 2027. During this time, do not:"]},{"k":"li","s":["eat, drink, smoke or chew gum in public in the daytime, including in your car"]},{"k":"li","s":["play loud music or dance"]},{"k":"li","s":["swear in public"]},{"k":"p","s":["Get more advice when you arrive from your tour guide, hotel or business contacts."]},{"k":"p","s":["You should also:"]},{"k":"li","s":["check opening hours of shops and restaurants"]},{"k":"li","s":["be aware that if hotels and restaurants are providing food or drink in fasting hours, they may separate you from Islamic guests, for example with screens"]},{"k":"li","s":["be aware that most restaurants do not serve alcohol"]},{"k":"li","s":["follow local dress codes – clothing that does not meet local dress codes may cause more offence at this time"]},{"k":"li","s":["be aware that fasting can cause tiredness, particularly during the later afternoon and early evening"]},{"k":"li","s":["be patient and show tolerance"]},{"k":"hs","s":["Alcohol laws"]},{"k":"p","s":["It is illegal to drink or be under the influence of alcohol in a public place."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["There is zero tolerance for drugs-related offences. The penalties for trafficking, smuggling, using and possessing illegal drugs are severe and can include the death penalty depending upon the severity of the offence."]},{"k":"hs","s":["Mobile phone coverage"]},{"k":"p","s":["Mobile phone coverage can be patchy or unavailable in more remote areas, particularly in the south of Algeria. Some online maps may not be accurate in remote areas."]},{"k":"hs","s":["Using cameras in secure areas"]},{"k":"p","s":["It is illegal to bring drones, binoculars, telescopes and certain types of photography equipment into Algeria without authorisation. If you have any doubt about items you plan to bring with you, contact the ",["Algerian customs","https://www.douane.gov.dz/spip.php?page=contact"]," to check prior to your travel."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Sexual acts between people of the same sex are illegal in Algeria."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Family law and child custody"]},{"k":"p","s":[["Algerian family law","https://www.gov.uk/government/publications/algerian-family-code"]," is different from UK law. Mothers cannot renew their children’s passports without written consent from the father. Fathers can renew their children’s passports without needing the mother’s consent."]},{"k":"p","s":["Algerian nationals, including dual-nationals, who enter the country on an Algerian passport, must leave the country on an Algerian passport, so if you are travelling with a child who has British-Algerian dual nationality, and you are unable to access a valid Algerian passport for them, you will not be able to bring the child out of Algeria without the father’s written consent or permission from the Algerian courts."]},{"k":"hs","s":["Military service"]},{"k":"p","s":["If you are a British male of Algerian origin, you may be liable for national service even if you have been living outside of Algeria. You can contact the Algerian consulate near you to check your status prior to travelling to Algeria."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Algeria, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Algeria for up to 3 months after you first arrive. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["correct version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well."]},{"k":"p","s":["The Algerian authorities may ask to see an IDP. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["If you are planning to hire a car, check with your car hire company for information on their requirements before you travel."]},{"k":"hs","s":["Road conditions and safety"]},{"k":"p","s":["Algeria has a very high road traffic accident rate and driving can be erratic."]},{"k":"p","s":["There is very little lane discipline and often confusion about the right of way, especially at roundabouts. Take particular care when crossing roads on foot, even where there is a signal allowing you to do so."]},{"k":"p","s":["Be cautious driving on minor roads, particularly at night outside towns. Roads and vehicles may not have lighting."]},{"k":"p","s":["In Algeria roads can have:"]},{"k":"li","s":["sand drifts – slow down as you approach these"]},{"k":"li","s":["large potholes, which can appear quickly, particularly after heavy rain"]},{"k":"li","s":["large speed bumps"]},{"k":"p","s":["At military or police checkpoints, approach slowly, do not cross boundaries without permission and be prepared to show photo ID if asked."]},{"k":"p","s":["Check the availability of petrol stations before travelling long distances in remote areas."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["If you are taking a taxi, ask your hotel to phone a reputable firm and do not allow unknown passengers to join you. Ask the driver to collect you for the return journey as taxis are not widely available, particularly after dark."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["Rail travel is generally safe, although safety standards tend to be lower than those in the UK. There is a risk of petty crime on trains."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["Wildfires take place most summers, causing significant damage and risk to life where they take place. Fires could flare up without warning, especially during periods of extreme weather. The General Directorate of Civil Contingency has released advice on ",["how to help prevent wildfires and what to do if a wildfire breaks out near you","https://dgpc.dz/en/forest-fire-prevention/"],". Always follow local advice and stay away from high risk areas."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Parts of Algeria are prone to severe and dangerous flood damage. There have been instances where people have been killed, houses submerged and cars swept away."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["Earthquakes are a risk in the northern part of Algeria, including Algiers."]},{"k":"p","s":["In May 2003, a severe earthquake struck the Algiers area. There were over 2,200 dead and more than 10,000 injured. Smaller earthquakes happen regularly. In July 2014, an earthquake killed 6 people and injured 420."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 16 or 1021 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Algeria","https://travelhealthpro.org.uk/country/3/algeria#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See what ",["health risks you’ll face in Algeria","https://travelhealthpro.org.uk/country/3/algeria"],"."]},{"k":"p","s":["Altitude sickness is a risk in parts of Algeria. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Algeria"]},{"k":"p","s":["Facilities at private clinics are usually better than government hospitals. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"p","s":["English is not widely spoken and you may face communication difficulties if you do not speak Arabic or French."]},{"k":"p","s":["FCDO has a list of ",["medical providers in Algeria","https://www.gov.uk/government/publications/algeria-doctors"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Algeria"]},{"k":"p","s":["Ambulance: 1021"]},{"k":"p","s":["Fire: 14"]},{"k":"p","s":["Police: 17 or 1548"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Algeria"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=algeria"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Algeria"]," in Algeria"]},{"k":"li","s":["dealing with a ",["death in Algeria","https://www.gov.uk/government/publications/algeria-bereavement-death-abroad"]]},{"k":"li","s":["being ",["arrested or imprisoned in Algeria","https://www.gov.uk/government/publications/algeria-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/algeria/british-embassy-algeria"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/algeria/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Algeria","https://www.gov.uk/government/publications/overseas-business-risk-algeria"]," on how to manage political, economic, and business security-related risks."]}],"chars":19220,"change":"Updated information about customs rules, terrorism in Algeria, political situation and personal ID (‘Entry requirements’ and ‘Safety and security’ pages)."},"https://www.gov.uk/foreign-travel-advice/kuwait":{"r":"govuk","at":"2026-11-17T17:03Z","sha":"c5a16bd5abf712587eeb65010a9f53efc4e3d2040e2798996c28cfb40b6ec201","read":"https://www.gov.uk/api/content/foreign-travel-advice/kuwait","bytes":67180,"x":"fulltext v1","title":"Kuwait travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-14T00:00:00+00:00","mod":"2026-10-27T16:06:20+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Regional tensions"]},{"k":"p","s":["The context in the Middle East remains deeply unpredictable and the risk of sudden escalation is high. Since conflict began in early 2026, Iran has stated its intention to target locations associated with the US and Israel, including, but not limited to, organisations, businesses, facilities, and institutions. There have been strikes and retaliatory attacks by Iran and others across the region against civilian and US military infrastructure."]},{"k":"p","s":["British nationals in, or planning to travel through, the Middle East should be prepared for possible flight cancellations, airspace closures, and travel disruptions. You should:"]},{"k":"li","s":["read ",["If you’re affected by a crisis abroad - GOV.UK","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],". This includes guidance on “how to prepare for a crisis” with suggestions on what you might include in your emergency supplies and “what to do in a crisis”"]},{"k":"li","s":["sign up to FCDO Travel Advice ",["email alerts","https://www.gov.uk/foreign-travel-advice/kuwait/email-signup"]]},{"k":"li","s":["follow advice from the local authorities"]},{"k":"li","s":["monitor local and international media for the latest information, including updates relating to airports and airspace which could close at short notice"]},{"k":"li","s":["stay away from areas around security or military facilities"]},{"k":"li","s":["keep your departure plans under review, and ensure your travel documents are up to date"]},{"k":"li","s":["if advised to take shelter, stay indoors or find the nearest safe building or designated shelter. An interior stairwell or a room with as few external walls or windows as possible may provide additional protection. The greatest risk is from falling debris caused by intercepts, and you are safest inside a secure structure. Do not approach or touch any drone or missile fragments or unusual objects"]},{"k":"hs","s":["Travelling to or transiting through Kuwait"]},{"k":"p","s":["Kuwait International Airport is currently operating through Terminals 4 and 5, serving Kuwait Airways, Jazeera Airways and foreign carriers, while Terminal 1 remains closed. Flight schedules remain reduced. Check details with your airline before travelling and follow local guidance."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/kuwait/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Kuwait’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Kuwait set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the Kuwaiti Embassy in the UK:"]},{"k":"p","s":["2 Albert Gate London, SW1X 7JU"]},{"k":"p","s":["Telephone: 020 7590 3400"]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Kuwait, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"hs","s":["Previous travel to Israel"]},{"k":"p","s":["If your passport contains an Israeli stamp, you may be refused a visa or entry to Kuwait."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Kuwait."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["You can get a visa on arrival in Kuwait or online. More information is available from the ",["Kuwait Ministry of Interior","https://kuwaitvisa.moi.gov.kw/"],"."]},{"k":"p","s":["British citizens born in Afghanistan, Iran, Iraq, Lebanon, Pakistan, Sudan, Syria or Yemen are not eligible for visa on arrival and must obtain a visa from the Kuwaiti Embassy before travelling."]},{"k":"hs","s":["Checks at border control"]},{"k":"p","s":["You must be able to show:"]},{"k":"li","s":["a ticket for return or onward travel"]},{"k":"li","s":["proof of your accommodation, for example, a hotel booking"]},{"k":"li","s":["work visas (both public and private sector) require further documents from employer. See ",["further details on visas and requirements","https://www.e.gov.kw/sites/kgoenglish/Pages/Visitors/Visitors.aspx"]]},{"k":"hs","s":["Additional processing at airports"]},{"k":"p","s":["Kuwaiti authorities may apply additional checks to some British nationals on arrival, particularly those born outside the UK, including from parts of the Middle East or South Asia. This may result in delays, additional questioning, or, in some cases, refusal of entry."]},{"k":"p","s":["Entry decisions are made by the Kuwaiti authorities."]},{"k":"p","s":["If you are concerned that you may be affected, consider checking with the Kuwaiti Embassy in London before you travel or applying for a visa in advance."]},{"k":"hs","s":["Working or living in Kuwait"]},{"k":"p","s":["For work or residency visas, apply to the Kuwaiti Embassy in London."]},{"k":"p","s":["If you’re applying for a residency visa, your passport must be valid for at least 2 years. Your employers should not keep your passport."]},{"k":"p","s":["For further information, ",["read about living in Kuwait.","https://www.gov.uk/guidance/living-in-kuwait"]]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, ",["see TravelHealthPro’s Kuwait guide","https://www.travelhealthpro.org.uk/country/122/kuwait#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Kuwait","https://e.gov.kw/sites/KGOEnglish/Pages/Business/InfoSubPages/InternationalTrade.aspx"],". You must declare anything that may be prohibited or subject to tax or duty. Failure to declare could result in:"]},{"k":"li","s":["imprisonment"]},{"k":"li","s":["refusal of entry and possible deportation"]},{"k":"p","s":["It is illegal to import:"]},{"k":"li","s":["narcotics"]},{"k":"li","s":["alcohol"]},{"k":"li","s":["gambling machines"]},{"k":"li","s":["pork and pork products"]},{"k":"li","s":["pornographic material"]},{"k":"hs","s":["Taking money into Kuwait"]},{"k":"p","s":["Declare cash or travellers cheques if the value is 3000 Kuwaiti dinars (£7,500) or more. You will get a certified declaration to show you brought it in with you. If you do not, your money could be seized when you leave."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Kuwait"]},{"k":"p","s":["In the context of regional escalation, Iran-aligned militia groups have threatened to target US interests across the region and have claimed attacks in Jordan and Iraq. US bases in Kuwait have also been hit by missile and drone fire. These groups are likely to continue to carry out these attacks in Kuwait."]},{"k":"p","s":["As was the case before the recent regional escalation, terrorist attacks in Kuwait cannot be ruled out. Terrorists have threatened to carry out attacks in the Gulf region, including on:"]},{"k":"li","s":["residential compounds"]},{"k":"li","s":["restaurants and hotels"]},{"k":"li","s":["beaches"]},{"k":"li","s":["shopping centres"]},{"k":"li","s":["mosques"]},{"k":"li","s":["military, oil, transport and aviation interests"]},{"k":"p","s":["Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Recent developments in the Middle East have heightened tensions in the region. Planned and pre-approved peaceful protests are legal, however these are for Kuwaiti citizens only."]},{"k":"p","s":["There have also been minor, isolated cases of vandalism aimed at some international companies, or calls for them to be boycotted."]},{"k":"p","s":["Be mindful of local sensitivities on these issues, stay away from demonstrations or developing crowds and follow the advice of the local authorities."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Violent crime against foreigners is rare. However, take care if you plan to travel to Jahra or Jleeb Al Shuyoukh, where there have been incidents of robberies, petty theft and road rage."]},{"k":"h","s":["Border crossings"]},{"k":"p","s":["It is illegal and dangerous to go near Kuwait’s borders without authorisation. Armed guards regularly patrol these areas."]},{"k":"hs","s":["Kuwait-Saudi Arabia border"]},{"k":"p","s":["It is easy to miss the border posts between Kuwait and Saudi Arabia. You must only use an authorised land border crossing and make sure to get an exit or entry stamp before you continue your journey."]},{"k":"hs","s":["Kuwait-Iraq border"]},{"k":"p","s":["If you plan to cross the border from Kuwait into Iraq, make sure you have the correct paperwork. See the ",["Iraqi Embassy to Kuwait","https://mofa.gov.iq/kuwait/en/"]," website for more information."]},{"k":"h","s":["Landmines and unexploded weapons"]},{"k":"p","s":["There are landmines and other unexploded weapons in Kuwait."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid off-road driving"]},{"k":"li","s":["stay on clearly marked identifiable tracks if you travel off-road"]},{"k":"li","s":["take great care even if an area has been officially cleared"]},{"k":"li","s":["not pick up metal, plastic or other objects"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"p","s":["Kuwait is a Muslim country. Always respect local traditions, customs, laws and religions. Make sure your actions do not offend other cultures or religious beliefs, especially during the holy month of Ramadan or if you visit religious areas."]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["As a visiting foreign national, you must always carry your passport. If you are resident in Kuwait, you must always carry your Kuwaiti civil identification card."]},{"k":"p","s":["Keep copies of your passport photo page and your visa or entry stamp in a separate place."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims. The dates vary by year and country. During this time, do not:"]},{"k":"li","s":["eat, drink, smoke or chew gum in public in the daytime, including in your car"]},{"k":"li","s":["play loud music or dance"]},{"k":"li","s":["swear in public"]},{"k":"p","s":["Get more advice when you arrive from your tour guide, hotel or business contacts."]},{"k":"p","s":["You should also:"]},{"k":"li","s":["check opening hours of shops and restaurants"]},{"k":"li","s":["be aware that if hotels and restaurants are providing food or drink in fasting hours, they may separate you from Islamic guests, for example with screens"]},{"k":"li","s":["follow local dress codes – clothing that does not meet local dress codes may cause more offence at this time"]},{"k":"li","s":["be aware that driving may be erratic, particularly when people are trying to get home at dusk"]},{"k":"li","s":["be patient and show tolerance"]},{"k":"hs","s":["Dress code"]},{"k":"p","s":["Dress and behave modestly in public, particularly in downtown or conservative areas. Women should avoid wearing shorts or tight-fitting or revealing clothing."]},{"k":"p","s":["Do not expose body piercings or tattoos that may be perceived as extreme or offensive – for example, you could be accused of violating religious sanctity for a tattoo of verse from the holy Quran in Arabic."]},{"k":"hs","s":["Relationships outside of marriage"]},{"k":"p","s":["It is illegal for an unmarried couple to live together in the same house or stay in the same hotel room. You will be asked to provide a marriage certificate if sharing a hotel room."]},{"k":"hs","s":["Public behaviour"]},{"k":"p","s":["It’s illegal to insult or humiliate any person verbally or through obscene gestures in a public place, including a police officer, public official or private individual. Police may arrest you and conviction may lead to prosecution, imprisonment, or immediate deportation."]},{"k":"p","s":["It is frowned on for men and women to show affection in public."]},{"k":"hs","s":["Alcohol laws"]},{"k":"p","s":["Alcohol is illegal. Buying, selling or carrying it, as well as public intoxication, can lead to fines, imprisonment and deportation. Consuming illegally produced alcohol poses severe health risks, including methanol poisoning, which can cause blindness, organ failure or death."]},{"k":"hs","s":["Illegal drugs penalties"]},{"k":"p","s":["Kuwait has zero tolerance for drug-related offences. Penalties for drug smuggling or trafficking include the death sentence. Offences involving minors or committed in schools, hospitals, prisons or other protected locations can result in life imprisonment or the death penalty."]},{"k":"p","s":["Possession or use of illegal drugs, including for small or residual amounts, can lead to a prison sentence of between 5 and 10 years, and heavy fines. Bail is not usually given and even if found not guilty, defendants can expect to spend several months in detention while the case progresses through the judicial system."]},{"k":"p","s":["Wearing, using, or displaying items that promote or encourage narcotics, including logos on clothing, constitutes an offence and may result in significant fines."]},{"k":"hs","s":["Using cameras in secure areas"]},{"k":"p","s":["It is illegal to photograph or take videos of:"]},{"k":"li","s":["government buildings"]},{"k":"li","s":["military buildings"]},{"k":"li","s":["industrial buildings or oil-related infrastructure"]},{"k":"li","s":["other restricted areas such as borders and oil fields"]},{"k":"li","s":["record people without their knowledge or consent"]},{"k":"hs","s":["Unpaid fines and bills"]},{"k":"p","s":["All foreign nationals must pay traffic fines, phone bills and utility bills before they leave Kuwait. The Kuwaiti authorities may:"]},{"k":"li","s":["stop you from leaving the country"]},{"k":"li","s":["arrest you, or send you to prison"]},{"k":"li","s":["fine you"]},{"k":"li","s":["deport you, and not allow you to return to Kuwait"]},{"k":"li","s":["refuse renewal of your residency card or re-entry visa"]},{"k":"hs","s":["Financial crimes"]},{"k":"p","s":["Bouncing cheques is illegal and the law does not provide for offenders to be released from custody on bail."]},{"k":"hs","s":["Commercial disputes"]},{"k":"p","s":["If you’re involved in a commercial dispute with a Kuwaiti company or individual, the Kuwaiti authorities may prevent you from leaving the country until it is resolved."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex activity is illegal."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Kuwait, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["If you have a visit visa, you can drive in Kuwait using a UK photocard driving licence. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["correct version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well."]},{"k":"p","s":["There is also ",["guidance on driving if you live in Kuwait","https://www.gov.uk/guidance/living-in-kuwait#driving-in-kuwait"],"."]},{"k":"hs","s":["Driving offences"]},{"k":"p","s":["Kuwait has introduced stricter traffic laws, with significantly increased fines and penalties. Offences such as speeding, using a mobile phone while driving, and running red lights can result in heavy fines, imprisonment or deportation."]},{"k":"hs","s":["Car insurance"]},{"k":"p","s":["You must get third-party insurance in Kuwait before you drive."]},{"k":"p","s":["If you hire a car, you can usually get insurance through the hire company. If you drive a relative or friend’s car, you’re responsible for getting insurance. You must always keep the insurance document with you while driving."]},{"k":"hs","s":["Car accidents"]},{"k":"p","s":["If you have a major accident, where there are serious injuries or a vehicle is not drivable:"]},{"k":"li","s":["stay with your vehicle if it is safe to do so"]},{"k":"li","s":["call the police on 112"]},{"k":"li","s":["do not move the vehicle before the police arrive"]},{"k":"p","s":["If you have a minor accident, where there are no serious injuries:"]},{"k":"li","s":["take pictures of vehicle damage if it is safe to do so"]},{"k":"li","s":["record licence plate numbers of vehicles involved"]},{"k":"li","s":["move your vehicle to avoid blocking traffic if it is drivable - you can get a fine if you do not do this"]},{"k":"li","s":["call the police on 112 and follow their instructions"]},{"k":"hs","s":["Drink-driving"]},{"k":"p","s":["Drink-driving is a serious offence in Kuwait. If you are tested and found to have any alcohol in your system, you may get a fine, imprisonment, or deportation and the withdrawal of your driving licence."]},{"k":"hs","s":["Driving conditions"]},{"k":"p","s":["Driving conditions are hazardous. Many drivers pay little attention to other road users and may:"]},{"k":"li","s":["drive faster than speed limits"]},{"k":"li","s":["switch lanes without warning"]},{"k":"li","s":["ignore traffic lights"]},{"k":"li","s":["use mobile phones while driving"]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["Many areas of the Gulf are highly sensitive, including near:"]},{"k":"li","s":["maritime boundaries"]},{"k":"li","s":["Bubiyan and Warbah, northern Gulf islands"]},{"k":"li","s":["Abu Musa and the Tunbs, southern Gulf islands"]},{"k":"p","s":["The area of the northern Gulf between Iran, Iraq and Kuwait has not been demarcated, and vessels entering this area have been detained and inspected. There have been occasional arrests. Make careful enquiries before entering these waters or visiting ports."]},{"k":"p","s":["Take extra care when sailing in Kuwaiti waters – regional tensions may affect your planned route. There may be an increased risk of attack on vessels in the Gulf of Oman, North Arabian Sea, Gulf of Aden and Bab El Mandeb regions."]},{"k":"p","s":["Take care when travelling by dhow, as the safety of these sailing vessels may not be up to UK standards. Make sure life jackets are available."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Kuwait","https://travelhealthpro.org.uk/country/122/kuwait#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"h","s":["Air quality"]},{"k":"p","s":["Poor outdoor air quality is a risk in Kuwait. Read about the risks from poor air quality on ",["TravelHealthPro","https://travelhealthpro.org.uk/disease/219/outdoor-air-quality"],"."]},{"k":"p","s":["You can find further information and advice on air quality on the ",["World Health Organization (WHO)","https://www.who.int/health-topics/air-pollution"]," website and check air quality levels on the ",["World Air Quality Index Website","https://aqicn.org/map/europe/"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"p","s":["Under new rules in Kuwait, all visitors must obtain permission from the Kuwaiti authorities to carry certain prescription drugs before arrival. This requirement applies to many commonly prescribed medications."]},{"k":"h","s":["Healthcare in Kuwait"]},{"k":"p","s":["There is a state medical service with local clinics and several good hospitals. There are also private medical and dental facilities."]},{"k":"p","s":["Private medical fees are high. The Kuwaiti government controls fees and has increased them for foreign residents and visitors. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment and repatriation."]},{"k":"p","s":["If you work in Kuwait, check whether your employer provides appropriate private medical insurance which includes repatriation. If not, you’re strongly advised to take out personal medical insurance for yourself and any dependants."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Kuwait","https://www.gov.uk/government/publications/kuwait-list-of-medical-facilities-and-repatriation-companies"]," where some staff will speak English."]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Kuwait","https://www.gov.uk/guidance/living-in-kuwait#healthcare"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Kuwait"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Kuwait"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Kuwait"]," in Kuwait"]},{"k":"li","s":["dealing with a ",["death in Kuwait","https://www.gov.uk/government/publications/kuwait-bereavement-information"]]},{"k":"li","s":["being ",["arrested or imprisoned in Kuwait","https://www.gov.uk/government/publications/kuwait-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/kuwait/british-embassy-kuwait-city"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/kuwait/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Kuwait","https://www.gov.uk/government/publications/overseas-business-risk-kuwait"]," on how to manage political, economic, and business security-related risks."]}],"chars":20016,"change":"Updated information about regional tensions (‘Warnings and insurance’ page)."},"https://theconversation.com/microsoft-has-suffered-a-global-outage-a-tech-expert-explains-what-went-wrong-296588":{"r":"conversation","at":"2026-11-17T17:03Z","sha":"0cbfed7fa0434abd3c62926a3c84d3d3790014b6e0efaec45b98d2623111f7ba","read":"https://theconversation.com/microsoft-has-suffered-a-global-outage-a-tech-expert-explains-what-went-wrong-296588","bytes":178003,"x":"fulltext v1","title":"Microsoft has suffered a global outage. A tech expert explains what went wrong","by":[{"n":"Mahmoud Elkhodr","r":"Senior Lecturer in Information and Communication Technologies, CQUniversity Australia"}],"pub":"2026-11-13T01:26:45Z","mod":"","blocks":[{"k":"p","s":["Microsoft has suffered a major global outage, bringing many of its widely used tools, including email and cloud storage, to a standstill."]},{"k":"p","s":["According to outage tracking site DownDetector, some 130,000 people reported issues accessing Microsoft Outlook as of early Thursday afternoon US Eastern time (early Friday morning in Sydney). In a ",["statement on X","https://x.com/MSFT365Status/status/2120974801388904932"],", the tech giant said it was “aggressively pursuing all pathways to reduce impact” and “restarting affected servers to return them to service”."]},{"k":"p","s":["In an ",["article for The Conversation","https://theconversation.com/what-would-happen-if-the-internet-went-down-295249"]," last month, I explained how the whole internet is unlikely to go down but several services can become unavailable together when they rely on shared systems."]},{"k":"p","s":["This outage shows precisely what happens when that shared infrastructure fails – and why we must prepare for digital outages in a similar way we do for natural disasters."]},{"k":"h","s":["Beyond missed emails or workplace meetings"]},{"k":"p","s":["The ",["list of services","https://www.abc.net.au/news/2026-11-13/microsoft-outage-affects-users-worldwide/107381050"]," Microsoft says are “potentially impacted” by the outage is long. It includes services used for email, document sharing, meetings and managing tasks, such as Outlook, Microsoft Teams, SharePoint Online, Microsoft Copilot 365, Microsoft Planner and Microsoft Exchange Online. It also includes Microsoft Defender, a cloud-based cybersecurity service."]},{"k":"p","s":["With so many digital services affected, the real-world impacts of the outage have been widespread, and go far beyond missed emails or workplace meetings."]},{"k":"p","s":["For example, family violence workers ",["reportedly","https://www.abc.net.au/news/2026-11-13/microsoft-outage-affects-users-worldwide/107381050"]," can’t access databases which contain client details. Schools can’t provide online lessons for remote students. Psychologists can’t provide telehealth consultations. Businesses are unable to process orders. Job hunters are unable to make it to planned interviews. Some government service centres have been forced to closed."]},{"k":"p","s":["The disruption also reached services ",["outside Microsoft","https://www.reuters.com/technology/microsoft-365-outlook-down-thousands-us-users-downdetector-shows-2026-11-12/"],". OpenAI and Anthropic reported problems with the tools that connect their artificial intelligence (AI) services to Microsoft 365."]},{"k":"p","s":["This shows how a problem in one part of the digital world can affect tools that appear separate, and even services provided by other companies."]},{"k":"p","s":["The outage comes ",["after other disruptions","https://www.forbes.com.au/news/world-news/microsoft-servers-crash-in-global-outage/"]," to Microsoft services earlier this year. For example, in January, Outlook, Teams and other Microsoft 365 services were down for hours. Then in August, Microsoft Outlook and Exchange Online were disrupted by a code update which took several days to fix."]},{"k":"h","s":["A shifting account of what went wrong"]},{"k":"p","s":["As of early Friday afternoon Sydney time, Microsoft has not yet named a root cause of the outage, and its account of the failure has ",["shifted since it was first reported","https://x.com/MSFT365Status/status/2120974801388904932"],"."]},{"k":"p","s":["Initially the company said elevated load across multiple regions was reported first. It then clarified the load was not driven by an increase in traffic, but a large number of servers becoming unexpectedly unavailable."]},{"k":"p","s":["Attention then moved to the automated “health checks” Microsoft uses to judge whether a server is fit to carry traffic, and to the component that processes them."]},{"k":"p","s":["The company described a core process on the affected servers as becoming “overwhelmed”. Software deployments and configuration changes were paused while recent changes were reviewed, although none was found to correlate with the start of the disruption."]},{"k":"p","s":["The evidence does not suggest a cyberattack."]},{"k":"p","s":["A distributed denial-of-service attack works by flooding a service with requests from outside until legitimate ones can no longer be answered. Microsoft’s own statement that overall traffic had not increased is difficult to reconcile with that pattern. No evidence of malicious activity has been disclosed, and no group has claimed responsibility."]},{"k":"p","s":["Indeed, ",["Microsoft said","https://www.abc.net.au/news/2026-11-13/microsoft-outage-affects-users-worldwide/107381050"],": “There’s no indication this is a cyber attack.”"]},{"k":"p","s":["The more mundane explanation fits better. Health checks exist to protect a service by withdrawing servers that appear unwell. When the machinery making that judgement is itself at fault, healthy capacity can be removed, and the servers that remain are left to absorb work they were never sized for."]},{"k":"p","s":["Outages of this scale are more often self-inflicted in this way than they are the work of attackers, as the August disruption to Microsoft email by a code update illustrates."]},{"k":"p","s":["Until a post-incident review is published, however, that remains an inference drawn from Microsoft’s own updates rather than a settled account."]},{"k":"p","s":["Microsoft has not yet been able to fix the outage entirely. It says that some of the ",["affected servers are working again","https://x.com/MSFT365Status/status/2120974801388904932"],", but they “can become unresponsive again once they begin receiving traffic”."]},{"k":"h","s":["Planning for outages like we do for bushfires"]},{"k":"p","s":["This outage reinforces the need for all of us to better prepare for digital outages. For individuals, this can involve storing essential information, such as contacts and medical prescriptions, offline in case of an outage."]},{"k":"p","s":["Organisations that rely on one digital provider such as Microsoft or Google for tasks must also prepare back up plans. Crucially, they must also test these back plans to make sure they work in practice and don’t simply exist on paper – similar to how they conduct fire drills and how communities practice bushfire evacuations."]},{"k":"p","s":["As more aspects of our lives become connected – from cars and homes to workplaces, transport and healthcare – and AI becomes more widely used, the consequences of digital disruption may grow."]},{"k":"p","s":["Building resilience must be part of how we plan for that future."]}],"chars":5366},"https://www.gov.uk/foreign-travel-advice/russia":{"r":"govuk","at":"2026-11-17T17:18Z","sha":"5e2ef24eb401a60eb9d621946723278c7a58215cb6a6163aac1f6d450893e62c","read":"https://www.gov.uk/api/content/foreign-travel-advice/russia","bytes":116151,"x":"fulltext v1","title":"Russia travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-13T00:00:00+00:00","mod":"2026-09-18T11:01:11+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["FCDO advises against all travel to Russia"]},{"k":"p","s":["FCDO advises against all travel to Russia due to the risks and threats from its continuing invasion of Ukraine, including:"]},{"k":"li","s":["security incidents, such as drone attacks, and Russian air defence activity"]},{"k":"li","s":["lack of flights to return to the UK"]},{"k":"li","s":["limited ability for the UK government to provide support"]},{"k":"p","s":["There is an increased risk of British nationals being detained in Russia, including if the Russian authorities suspect you of engaging in or supporting activities against Russian law, even if activities took place outside Russia. ",["See ‘Risk of arrest and detention’ on ‘Safety and security’","https://www.gov.uk/foreign-travel-advice/russia/safety-and-security"],"."]},{"k":"p","s":["Russia has a track record of targeting foreign nationals and holding them in detention as leverage over other countries. FCDO’s ability to assist you in these circumstances is extremely limited."]},{"k":"p","s":["There is also a high likelihood terrorists will try to carry out attacks, including in major cities. See ",["‘Safety and security’","https://www.gov.uk/foreign-travel-advice/russia/safety-and-security"],"."]},{"k":"p","s":["Ongoing drone attacks and associated Russian air-defence activity may increase risks to civilian aviation and can lead to short-notice restrictions on airspace use and airport operations. See ",["‘Safety and security’","https://www.gov.uk/foreign-travel-advice/russia/safety-and-security"]]},{"k":"h","s":["Limited UK government support"]},{"k":"p","s":["The British Embassy in Moscow and British Consulate in Ekaterinburg are open, but the situation could change at short notice."]},{"k":"p","s":["In-person UK government support in Russia is limited. It is very limited in parts of Russia because of the security situation and the size of the country, particularly in the North Caucasus."]},{"k":"p","s":["If you need support, call our 24-hour helpline +7 495 956 7200 and select the option for consular services for British nationals."]},{"k":"p","s":["Contact the Russian emergency services on 112."]},{"k":"hs","s":["Dual nationals"]},{"k":"p","s":["If you hold both British and Russian nationality, Russian authorities will treat you as a Russian citizen. This limits the consular assistance the UK government can provide. If you are arrested or detained, Russian authorities are unlikely to allow UK consular staff to visit or assist you."]},{"k":"p","s":["Russian nationals are required to notify Russian authorities of any second nationality, including British, within 60 days of acquiring that nationality, or within 60 days of returning to Russia if the British/ foreign nationality was obtained outside of Russia. Parents are responsible for notification on behalf of their children aged under 18. Failure to comply can result in criminal liability. Your British passport may be confiscated by the Russian authorities and not returned. Penalties can include a fine of up to 200,000 Russian rubles (or up to one year of income) and/or compulsory work for up to 400 hours."]},{"k":"hs","s":["Military Service"]},{"k":"p","s":["Russia operates a conscription-based military system. Men aged 18 to 30 with Russian citizenship may be called up for two-year compulsory military service. Conscription campaigns continue throughout the year."]},{"k":"p","s":["Russian law prevents eligible individuals from leaving Russia once their draft notice appears on the federal electronic draft register."]},{"k":"p","s":["If you receive a conscription notice via your account on the Russian State Services portal, you will be prohibited from leaving Russia. Failure to report to the conscription point within seven days of receiving the notice may result in penalties, restrictions on your rights, or detention."]},{"k":"p","s":["In addition to regular conscription, Russia has declared a partial mobilisation. Military recruitment is ongoing, and anyone with Russian citizenship may be drafted."]},{"k":"h","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/russia/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK who choose to travel against Foreign, Commonwealth & Development Office (FCDO) advice. It is based on the UK government’s understanding of Russia’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Russia set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Russian Embassy or a consulate in the UK","https://london.mid.ru/en/contact/"],"."]},{"k":"h","s":["Biometrics"]},{"k":"p","s":["Foreigners entering Russia will be required to register, on arrival, their biometric details such as fingerprints and photographs."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Russia, your passport must have an ‘expiry date’ at least 6 months after the date your visa expires."]},{"k":"p","s":["You cannot enter Russia using a visa in an expired passport, even if you’re also carrying a new, valid passport. You will need to apply for a new visa or visa transfer."]},{"k":"p","s":["Sign your passport before you travel if it was issued after January 2017. Some British nationals have been denied entry for not signing their passports."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Traveling with children"]},{"k":"p","s":["Children under 18 years old must carry a notarised travel permission from one of their parents or legal guardians if they’re travelling out of Russia without their parent or legal guardian."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"hs","s":["British-Russian dual nationals"]},{"k":"p","s":["If you have dual British-Russian nationality and travel to Russia to renew your Russian passport, it may take up to 4 months to get your new passport. You will not be able to leave Russia on your British passport if you entered Russia on your Russian passport. You will have to stay in Russia until your new Russian passport is issued."]},{"k":"p","s":["Children born outside of Russia and added to their parents’ Russian passports may need their own passport to leave Russia. Check with the ",["Russian Embassy in the UK","https://london.mid.ru/en/"]," before you travel."]},{"k":"p","s":["See ",["Warnings and insurance page","https://www.gov.uk/foreign-travel-advice/russia"]," for information about severely limited UK government support and compulsory military service for British-Russian dual nationals."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must get a visa before you travel."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["See the ",["Russia Visa Centre","https://russia-visacentre.com/en/visa/united-kingdom/russia"]," for further information on how to apply for a visa, including processing time and fast track services."]},{"k":"p","s":["If you live in the UK and are aged 12 or over, you must go to a ",["visa application centre in London, Manchester or Edinburgh","https://russia-visacentre.com/en/visa/united-kingdom/russia"]," to submit biometric data (fingerprints)."]},{"k":"p","s":["If you’re a British national with a Russian national in your immediate family, you can apply for a ",["multi-entry private visa","https://russia-visacentre.com/en/visa/united-kingdom/russia/visa-types/family-members-of-the-russian-citizens-visa"]," for up to one year. Check what you need for your stay with the ",["Russian Embassy in the UK","https://london.mid.ru/en/"],"."]},{"k":"p","s":["The Russian authorities strictly enforce visa and immigration laws. Before you travel, check:"]},{"k":"li","s":["your visa details are correct"]},{"k":"li","s":["the terms and conditions of your visa"]},{"k":"hs","s":["Overstaying your visa"]},{"k":"p","s":["If you overstay your visa, you may face fines, court hearings, deportation or a ban from re-entry."]},{"k":"p","s":["Foreign nationals who have exceeded the terms of their legal stay in Russia and don’t have the necessary permits or visa will be entered on an official surveillance register, deported from Russia, and banned from re-entering."]},{"k":"h","s":["Leaving Russia"]},{"k":"p","s":["You may not be able to exit Russia if you have any unpaid debts, fines or penalties in Russia. Check if you have any outstanding payments using the ",["Russia State Bailiff’s Services portal","https://fssp.gov.ru/iss/ip/"]," (in Russian) or ",["Russian State Services portal","https://www.gosuslugi.ru/"]," (in Russian). You may not be able to access these portals from outside of Russia."]},{"k":"h","s":["Immigration cards"]},{"k":"p","s":["You must sign an immigration card at passport control every time you enter Russia."]},{"k":"p","s":["Immigration officials keep one half. They return the other half to you. You must keep it and show it at passport control when you leave Russia, or your departure could be delayed."]},{"k":"p","s":["You will need to show your immigration card when you exchange money or check into your accommodation."]},{"k":"h","s":["Questioning on arrival in Russia"]},{"k":"p","s":["There have been intensive security checks on foreign nationals at the Russian border. Some British and dual British-Russian nationals have been:"]},{"k":"li","s":["stopped and questioned about political views or contacts with Ukraine or Ukrainians"]},{"k":"li","s":["had fingerprints and DNA swabs taken"]},{"k":"li","s":["asked to provide data from phones and other electronic devices"]},{"k":"li","s":["held for many hours for identity and electronic device checks, sometimes without access to refreshments"]},{"k":"p","s":["Under Russian law, you do not need to release your electronic device for checks unless you are presented with a search warrant. However, if you refuse to release your device, you may face substantial delays entering Russia due to continued questioning and pressure to cooperate, including threats of legal action."]},{"k":"p","s":["You should:"]},{"k":"li","s":["tell family, friends or colleagues about your travel plans and explain that the arrival process might take longer than usual"]},{"k":"li","s":["stay calm and avoid confrontation if you are stopped"]},{"k":"li","s":["be prepared for a long delay, and potentially to be refused entry to Russia"]},{"k":"p","s":["The UK government cannot interfere in Russian immigration decisions and cannot help you during questioning."]},{"k":"h","s":["Registering with the authorities"]},{"k":"p","s":["You must register with the local authorities if you’re staying anywhere for more than 7 working days. Your hotel will do this automatically. If you’re staying with someone, check that they’re doing this."]},{"k":"p","s":["You must show evidence of your registration at passport control when you leave Russia. Police also carry out routine checks. If you cannot show your registration and passport, you may be detained for up to 48 hours for identity checks or get a fine."]},{"k":"h","s":["Travelling between Russia and Belarus"]},{"k":"p","s":["As of 11 January 2025, foreign citizens with a Belarusian or Russian visa may enter, leave, stay or transit through either Belarus or Russia during the period of validity of the visa. This is limited to certain international border crossing points. For more information, see the website of the ",["Russian Ministry of Foreign Affairs","https://mfa.gov.by/en/press/news_mfa/e90f53f504e4694f.html"],"."]},{"k":"hs","s":["By air"]},{"k":"p","s":["You will need to go through immigration control if you fly to Russia from Belarus or from Belarus to Russia."]},{"k":"hs","s":["By road"]},{"k":"p","s":["You can only cross the land border between Russia and Belarus by road through a limited number of authorised crossing points. Crossing at any other place is prohibited. Authorised crossing points are:"]},{"k":"li","s":["Yukhnovichi-Doloscy (A-117)"]},{"k":"li","s":["Ezerische – Nevel’ (M-20)"]},{"k":"li","s":["Liozno-Kruglovka (A-141)"]},{"k":"li","s":["Red’ki-Krasnaya Gorka (M-1)"]},{"k":"li","s":["Zvenchatka- Dubovichka (A-101)"]},{"k":"li","s":["Selische-Novozybkov (M-13)"]},{"k":"hs","s":["By rail"]},{"k":"p","s":["Contact your train or tour operator before booking your travel to make sure you enter Russia through an immigration checkpoint. Contact the nearest Russian embassy or consulate for advice on rail travel."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Russia guide","https://travelhealthpro.org.uk/country/186/russia#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules on what you can take into and out of Russia."]},{"k":"p","s":["If you fail to comply with Russian customs regulations, you may face fines, confiscation of goods or prosecution. Check the ",["Federal Customs Service of Russia guidance","https://eng.customs.gov.ru/activities/individuals"]," for details (the site may not be accessible from outside Russia)."]},{"k":"h","s":["Goods requiring a customs declaration"]},{"k":"p","s":["You must complete a customs declaration form if you import goods worth more than 10,000 US dollars (or the same amount in other currencies)."]},{"k":"p","s":["You must also complete a customs declaration when bringing any of the following into Russia, regardless of their value:"]},{"k":"li","s":["items of cultural and historical significance"]},{"k":"li","s":["rare plants or animals"]},{"k":"li","s":["vehicles"]},{"k":"li","s":["Russian state awards"]},{"k":"li","s":["weapons or their components"]},{"k":"li","s":["medicines containing potent, toxic, or psychoactive substances"]},{"k":"p","s":["Russian law requires accompanying documentation for many of these items."]},{"k":"p","s":["Possessing even small quantities of any illegal drugs, including cannabis, carries severe penalties. See ",["‘Illegal drugs’ for more information","https://www.gov.uk/foreign-travel-advice/russia/safety-and-security#illegal-drugs"],"."]},{"k":"hs","s":["Cannabidiol (CBD)"]},{"k":"p","s":["Cannabidiol (CBD) is illegal in Russia, even in products purchased legally elsewhere. This includes oils, edibles and vapes. If you’re found with CBD products you may be sentenced to several years’ imprisonment."]},{"k":"hs","s":["Cash and financial instruments"]},{"k":"p","s":["You may bring cash in any currency and travellers’ cheques into or out of Russia without declaring them if their combined value does not exceed the equivalent of 10,000 US dollars."]},{"k":"p","s":["You cannot leave Russia with cash in any currency or travellers’ cheques if their combined value is more than the equivalent of 10,000 US dollars, even if you complete a customs declaration."]},{"k":"hs","s":["Electronic items"]},{"k":"p","s":["You must obtain a licence before travelling if you plan to take certain electronic equipment with you to Russia, including GPS devices. The number of electronic items you can bring for personal use is limited."]},{"k":"p","s":["Check the requirements for entering and exiting Russia with electronic items on ",["the Federal Customs Service website","https://eng.customs.gov.ru/activities/individuals/movement/rules-for-moving-goods"]," (the site may not be accessible from outside Russia)."]},{"k":"hs","s":["Antiques and art"]},{"k":"p","s":["Russia has strict regulations on the import and export of antiques, artwork, and items of historical significance."]},{"k":"p","s":["You must get an ",["export permit from the Ministry of Culture","https://culture.gov.ru/about/departments/departament_kulturnogo_naslediya/activities/409789/"]," (the site may not be accessible from outside Russia) and declare each item when you leave. It is illegal to import or export items without a permit."]},{"k":"hs","s":["Customs declaration forms"]},{"k":"p","s":["Make sure a customs official stamps your customs declaration form when you enter. If you do not get a stamp, the authorities may confiscate your money or goods when you leave, and you may be fined."]},{"k":"p","s":["Keep receipts of any purchases in case you need to show them when you leave Russia."]},{"k":"h","s":["Money and banking"]},{"k":"p","s":["The Russian economy is unstable. This could make access to goods and services difficult."]},{"k":"p","s":["Mastercard and Visa are not operating in Russia. Mastercard and Visa cards issued outside Russia will not work at Russian shops or ATMs. Cards issued inside Russia will work in, but not outside, Russia. You may not be able to access your money through Russian banks or make payments to Russian businesses with non-Russian credit or debit cards."]},{"k":"p","s":["For all other credit or debit cards, let your provider know you’re travelling to Russia to avoid your card being blocked for anti-fraud reasons."]},{"k":"p","s":["There are few remaining methods of transferring money to Russia. UK Banks may refuse to transfer funds to even non-sanctioned banks. There have also been several cases of UK bank accounts of non-UK residents being closed at short notice. Make sure that you have enough money to cover your stay and have plans on how to access funds if your current methods become unavailable."]},{"k":"hs","s":["Buying Russian roubles"]},{"k":"p","s":["It is illegal to pay directly for general transactions in Russia using foreign currency. It is difficult to get Russian roubles in high street banks in the UK. If you want to buy roubles in Russia, you must take US dollars or euros to exchange."]},{"k":"p","s":["Only change money at banks, hotels and exchange bureaus. It is illegal to change money from street traders."]},{"k":"p","s":["The UK government has sanctioned several major Russian banks. This means British nationals are banned from making funds available to these banks. See more ",["information about Russian sanctions","https://www.gov.uk/government/collections/uk-sanctions-on-russia"]," and what this means for British nationals."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Russia"]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks in Russia."]},{"k":"p","s":["Terrorist attacks could be indiscriminate, including in places visited by foreign nationals, such as:"]},{"k":"li","s":["large gatherings, such as concerts"]},{"k":"li","s":["popular tourist sites"]},{"k":"li","s":["seasonal, festive, or religious activities in public places"]},{"k":"li","s":["areas that are not controlled by security, such as open-air events and markets"]},{"k":"li","s":["transportation networks"]},{"k":"p","s":["Terrorist attacks have taken place in Moscow and St Petersburg and other Russian cities in recent years, resulting in large numbers of casualties. Russia’s aviation has also been targeted."]},{"k":"p","s":["Examples of recent attacks include:"]},{"k":"li","s":["in March 2024, 145 people were killed in an attack at the Crocus City Concert Hall in Krasnogorsk near Moscow"]},{"k":"p","s":["Additional counter-terrorism procedures and restrictions may still be in place across the country. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"hs","s":["Terrorism in the North Caucasus"]},{"k":"p","s":["Terrorists are active in the North Caucasus. They have carried out a number of attacks mainly in Russia’s Dagestan region."]},{"k":"p","s":["Security services carry out regular counter-terrorism operations in the North Caucasus and across Russia. These can happen at short notice and may lead to travel restrictions."]},{"k":"p","s":["Examples of recent attacks include:"]},{"k":"li","s":["in June 2024 at least 20 people were killed after armed men attacked synagogues, churches and police in Dagestan"]},{"k":"h","s":["Security situation in Russia"]},{"k":"p","s":["The Russian invasion of Ukraine continues. There are reports of drone attacks and explosions in Russia, particularly near the Russian border with Ukraine, but also in and near large cities and infrastructure sites across Western and Central Russia. Associated Russian air defence activity may pose a threat to civilian aviation. Air space may close during drone attacks. This has led to frequent and unpredictable delays, diversions and cancellations to flights in and out of Russian airports. There have been several shootings in Moscow, often near to apartment blocks. There has also been a bombing near to a Moscow railway station."]},{"k":"p","s":["Check local media for the latest information. Be vigilant and avoid any political demonstrations or gatherings."]},{"k":"p","s":["The situation remains unpredictable and could escalate without warning."]},{"k":"h","s":["Leaving Russia"]},{"k":"p","s":["If you do not need to be in Russia, the FCDO strongly advises you to consider leaving."]},{"k":"p","s":["You cannot fly directly from Russia to the UK or through EU countries. There are limited commercial airlines with indirect flights including through the Middle East, Serbia, Azerbaijan, Central Asia, Georgia and Turkey. Check the latest information with your airline or travel provider."]},{"k":"hs","s":["Land border crossings"]},{"k":"p","s":["Land borders may be busy or closed. Be prepared for a long wait to exit Russia. Officials may question you at the border. During periods of unrest, check the local media for updates before travelling."]},{"k":"p","s":["Check entry requirements in:"]},{"k":"li","s":[["Finland travel advice","https://www.gov.uk/foreign-travel-advice/finland"]]},{"k":"li","s":[["Latvia travel advice","https://www.gov.uk/foreign-travel-advice/latvia"]]},{"k":"li","s":[["Estonia travel advice","https://www.gov.uk/foreign-travel-advice/estonia"]]},{"k":"li","s":[["Lithuania travel advice","https://www.gov.uk/foreign-travel-advice/lithuania"]]},{"k":"li","s":[["Norway travel advice","https://www.gov.uk/foreign-travel-advice/norway"]]},{"k":"p","s":["These and other European countries have restricted or banned the entry of vehicles registered in Russia. Check entry requirements before driving a vehicle registered in Russia into Europe."]},{"k":"p","s":["See information on:"]},{"k":"li","s":[["Finnish border crossings","https://raja.fi/en/frontpage"]," – the border between Finland and Russia is closed"]},{"k":"li","s":[["Latvian border crossings","https://www.rs.gov.lv/en/vehicle-border-crossing"]]},{"k":"li","s":[["Estonian border crossings","https://www.politsei.ee/en/procedure-for-crossing-the-estonian-russian-border"]," – the Narva-Ivangorod crossing is closed to vehicles but open to pedestrians"]},{"k":"li","s":[["Lithuanian border crossings","https://www.ltsiena.lt/yphis/index.action"]]},{"k":"h","s":["Staying in Russia"]},{"k":"p","s":["If you decide to stay in Russia, you should:"]},{"k":"li","s":["keep your departure plans under constant review"]},{"k":"li","s":["ensure travel documents are up to date"]},{"k":"li","s":["ensure you have enough money"]},{"k":"li","s":["follow local media"]},{"k":"li","s":["stay alert to security warnings and follow the advice of local authorities"]},{"k":"li","s":["take cover from drone attacks in buildings or underground and avoid windows"]},{"k":"li","s":[["sign up to email alerts for Russia travel advice","https://www.gov.uk/foreign-travel-advice/russia/email-signup"]]},{"k":"p","s":["Read guidance for people ",["affected by a crisis abroad","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],"."]},{"k":"h","s":["Political situation"]},{"k":"hs","s":["Russia’s invasion of Ukraine"]},{"k":"p","s":["Russia’s invasion of Ukraine continues. The situation is unpredictable and could escalate without warning. Stay alert and follow the advice of local authorities."]},{"k":"p","s":["Russia has heightened security measures in place, which are set by local authorities and differ between regions. They can introduce additional measures at short notice, especially near borders. This could include curfews, restrictions on movement and public gatherings, searches or seizure of private property and increased monitoring of communications."]},{"k":"hs","s":["Military activity in Kursk Oblast"]},{"k":"p","s":["There is military activity in Kursk and Belgorod oblasts. On 10 August, Russian authorities introduced a “counter-terrorist operation” regime in Kursk, Belgorod and Bryansk oblasts. The activity in these oblasts is mainly limited to regions which border Ukraine. However, military activity could spread to other areas. Travel advice for other oblasts could change at short notice. Follow any relevant instructions from local authorities."]},{"k":"hs","s":["Foreign fighters"]},{"k":"p","s":["If you travel to Russia to join the Russian army, or to help others engaged in the war with Ukraine, you could be breaking UK laws. You could be prosecuted when you return to the UK."]},{"k":"hs","s":["Risk of arrest and detention"]},{"k":"p","s":["On 28 December 2024, the Russian Criminal Code was revised, expanding the scope of potential liability for foreigners believed to be acting against Russian interests."]},{"k":"p","s":["If the Russian authorities suspect you of engaging in or supporting activities against Russian law, even if activities took place outside Russia, you may be:"]},{"k":"li","s":["deported"]},{"k":"li","s":["detained"]},{"k":"li","s":["investigated"]},{"k":"li","s":["prosecuted"]},{"k":"p","s":["Activities could include:"]},{"k":"li","s":["displaying LGBT+ symbols like the rainbow flag"]},{"k":"li","s":["expressing support for Ukraine on social media"]},{"k":"li","s":["making a financial contribution to organisations linked to Ukraine"]},{"k":"li","s":["helping Russian nationals evade conscription"]},{"k":"p","s":["If Russian authorities detain you, you could face months or years of imprisonment. Russia has a track record of targeting foreign nationals and holding them in detention as leverage over other countries. FCDO’s ability to assist you in these circumstances is extremely limited."]},{"k":"p","s":["If you are a British-Russian dual national, you are at risk of arrest, questioning or detention."]},{"k":"hs","s":["Getting help while in detention"]},{"k":"p","s":["It may take some time for the Russian authorities to tell us of your arrest or detention and to give us permission to visit you. They will control your access to your family during your detention. Conditions in Russian penitentiary institutions are poor."]},{"k":"p","s":["If you are a British-Russian dual national, we may not be informed of your arrest. The Russian authorities will treat you as a Russian national. They will not allow FCDO consular access to visit you."]},{"k":"hs","s":["Restrictions on publishing and distributing information"]},{"k":"p","s":["Journalists have been arrested for gathering and publishing information."]},{"k":"p","s":["There are severe restrictions on publishing and distributing information related to the Russian armed forces and any military operations. This includes images of, including the aftermath, of drone, military or terrorist attacks. People charged under these laws face heavy sentences."]},{"k":"p","s":["If you publish or distribute information considered ‘fake’ or from non-official Russian government sources, you could receive a fine or prison sentence of up to 15 years. This includes posting or sharing content on social media."]},{"k":"hs","s":["International sanctions against Russia"]},{"k":"p","s":["In response to Russia’s invasion, the UK and other governments have placed sanctions on Russia, including on its airlines. This can affect the situation in Russia and anyone travelling there. See more ",["information about Russian sanctions","https://www.gov.uk/government/collections/uk-sanctions-on-russia"]," and what this means for British nationals."]},{"k":"p","s":["International businesses and services have restrictions in place, including Mastercard and Visa, which means you may not be able to access money or other services. Read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/russia/warnings-and-insurance"]," and ",["entry requirements","https://www.gov.uk/foreign-travel-advice/russia/entry-requirements"],"."]},{"k":"hs","s":["Protests and demonstrations"]},{"k":"p","s":["Since Russia’s invasion of Ukraine, there have been anti-war protests across Russia. Demonstrators have been detained."]},{"k":"p","s":["Authorised rallies and demonstrations are allowed in cities and towns in Russia. Under Russian law, a single person can constitute a protest and could be subject to repercussions by Russian authorities. Unauthorised demonstrations can become violent, with a strong response from security forces."]},{"k":"p","s":["Check local media for the latest information, be vigilant and avoid demonstrations or large gatherings that may be considered political. Do not take photographs of or film political activities."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting your belongings"]},{"k":"p","s":["Be alert to the risk of mugging, pickpocketing and theft in the main tourist areas, around the main railway stations, vehicles and hotel rooms. You should not:"]},{"k":"li","s":["leave your bags unattended"]},{"k":"li","s":["openly carry expensive items or anything that might identify you as a tourist"]},{"k":"li","s":["walk about late at night alone"]},{"k":"li","s":["look after possessions of people you do not know"]},{"k":"li","s":["agree to go to a bar or a club with someone you have just met"]},{"k":"p","s":["Be wary of groups of people begging."]},{"k":"p","s":["Look after your passport, especially in major transport hubs and busy areas. British nationals have had passports stolen or lost in Moscow airports. Take care when passing through airports, particularly in the baggage collection area and outside the arrivals hall."]},{"k":"hs","s":["Drink spiking"]},{"k":"p","s":["Drink spiking, leading to robbery, violence or abuse, can happen. Victims are often left unconscious outside. This can be life-threatening in winter. Buy your own drinks and always keep them in sight."]},{"k":"hs","s":["Methanol poisoning"]},{"k":"p","s":["There have been deaths and cases of serious illness caused by alcoholic drinks containing methanol in Russia."]},{"k":"p","s":["In recent cases, deaths were linked to bootleg vodka sold in the Leningrad region. Authorities have arrested suspects, seized thousands of litres of illicit alcohol, and launched criminal investigations. In 2023, a counterfeit cider branded Mister Cider caused over 50 deaths, prompting product bans and enforcement action, but despite this, incidents have continued."]},{"k":"p","s":["Even small amounts of methanol can kill. It is not possible to identify methanol in alcoholic drinks by taste or smell. See ",["Travel Aware Spiking and methanol poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," for information about how to reduce the risks."]},{"k":"p","s":["Seek urgent medical attention if you or someone you are travelling with show the ",["signs of methanol poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," after drinking."]},{"k":"hs","s":["Violent crime"]},{"k":"p","s":["Violent criminals do not usually target foreign visitors. However, in St Petersburg gangs have targeted tourists for street crime."]},{"k":"hs","s":["Avoiding unregistered taxis"]},{"k":"p","s":["British nationals travelling in unregistered taxis have been victims of crime. Taxis that look official can be unlicensed. You should:"]},{"k":"li","s":["use a local taxi app to call a registered taxi"]},{"k":"li","s":["ask your hotel to call a taxi or give you the number of a reputable company"]},{"k":"li","s":["agree the fare before getting into the taxi or check that the meter is working"]},{"k":"p","s":["Do not flag down a taxi or share a taxi with strangers."]},{"k":"hs","s":["Dating services scams"]},{"k":"p","s":["Dating services scams have affected British nationals. Never send money to or buy items for anyone you have not met in person."]},{"k":"hs","s":["Money transfer scams"]},{"k":"p","s":["Be wary of sending money through untraceable transfer services. British nationals have lost money when sending it to unknown recipients without checking they’re genuine."]},{"k":"hs","s":["Fake police checks"]},{"k":"p","s":["The police do not need a reason to stop, question or detain you. Criminals posing as police officers have harassed and robbed tourists. If you’re stopped, always insist on seeing identification. Report any harassment or crime to the nearest police office."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry your passport with you as ID. Police carry out random checks, especially during periods of high security. You could get a fine or be detained for up to 48 hours if you cannot show your passport when asked. Copies are not accepted."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["You can be prosecuted for possessing even small quantities of any drugs, including cannabis. You should expect a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Airports in Russia have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Restricted military areas"]},{"k":"p","s":["Access to some areas, such as military and border zones, is restricted. You must get permission from local authorities before entering. If you do not have permission, the authorities may arrest, fine or deport you."]},{"k":"p","s":["You can find a list of restricted areas online (in Russian, you may not be able access the site from outside of Russia). Check with your tour operator or the ",["Russian Embassy in the UK","https://london.mid.ru/en/"]," if you’re unsure whether a tour or excursion will take you into a restricted area."]},{"k":"hs","s":["Taking photos in secure areas"]},{"k":"p","s":["Photography is illegal at any military, secure or official sites, including airports. There may not be warning signs in locations where photography is banned. You could be detained or arrested if you break the law."]},{"k":"hs","s":["Using drones"]},{"k":"p","s":["Due to current military activities, it is illegal to use drones in some regions. Check restrictions with the local authorities."]},{"k":"p","s":["You must get permission from the Russian aviation authority (in Russian) before using any unmanned aircraft systems (drones) in Russian airspace. You must tell them the flight route at least 24 hours in advance and keep in regular contact with them before and during the flight. You will get a fine if you do not comply."]},{"k":"hs","s":["Mobile phones"]},{"k":"p","s":["If you travel to Russia with a non-Russian SIM card, you may not be able to access mobile internet, SMS or other services. Buying a local-network SIM card in Russia can be difficult for visitors and could take up to 2 weeks to complete. Make sure your friends and relatives know how to contact you if your mobile phone does not work."]},{"k":"p","s":["You need to present your passport or other ID and pass biometric checks to buy a Russian sim card from local providers in Russia. You may be asked to perform these checks even if you have had a local SIM for some time."]},{"k":"p","s":["You can continue using your UK SIM in Russia without any local identity checks as long as your UK mobile company provides roaming service for Russia."]},{"k":"p","s":["Any SIM which has not been connected to the Russian network for 72 hours will not be able to connect to the internet or send SMS when they are first switched on. You may have to wait for some time for the services to resume. This may vary from several hours to several days. Some networks may allow you to complete a set of actions to get your access restored quicker."]},{"k":"p","s":["Make sure friends and relatives know how to contact you if your mobile phone does not work."]},{"k":"hs","s":["Cybersecurity laws"]},{"k":"p","s":["There are increasing restrictions to limit access to content posted on the internet, including social media platforms. Meta (Facebook and Instagram), X and LinkedIn are blocked in Russia. Access to other websites can be unreliable."]},{"k":"p","s":["More information is available from the ",["Federal Service for Surveillance of Communications, Information Technology and Mass Media","https://rkn.gov.ru/"]," (in Russian)."]},{"k":"hs","s":["Racial discrimination"]},{"k":"p","s":["Most visitors experience no problems, but racial discrimination can happen in some areas. If you’re of African, Asian or Caribbean descent, you may receive unwanted attention in public places. Take care, particularly when travelling late at night."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Homosexuality is not illegal in Russia but there are considerable legislative restrictions which target the LGBT+ community. In January 2024 a Russian Supreme Court judgement came into force banning the so-called ‘international LGBT movement’ and designating it as ‘extremist’. ‘LGBT propaganda’ legislation bans people from promoting ‘non-traditional sexual relations’. If charged, foreign citizens could face:"]},{"k":"li","s":["fines"]},{"k":"li","s":["up to 15 days in jail"]},{"k":"li","s":["deportation"]},{"k":"p","s":["Attitudes towards the LGBT+ community and LGBT+ issues are less tolerant than in the UK and vary in different locations. Government officials have made derogatory comments to LGBT+ individuals. Same-sex couples showing affection in public may receive negative attention."]},{"k":"p","s":["There are no laws to protect LGBT+ people from discrimination on the grounds of sexual orientation or gender identity."]},{"k":"p","s":["Recent laws targeting LGBT+ communities include:"]},{"k":"li","s":["in 2012, Moscow Pride was banned for 100 years"]},{"k":"li","s":["in 2022, a ban on the ‘demonstration of LGBT information, promotion of non-traditional sexual relations and change of gender’ to children and adults through the internet, films, advertisement, audio visual services and books (the “gay propaganda” law)"]},{"k":"p","s":["In November 2023, the Russian Supreme Court banned the so-called ‘international LGBT movement’, designating it as ‘extremist’. The court provided no definition of ‘international LGBT movement’."]},{"k":"p","s":["Displaying ‘extremist’ symbols and being a member of and donating money to ‘extremist’ organisations are criminal offences. This decision came in to force in January 2024. It is unclear how the authorities will implement the ruling but there have been reports of persecution for displaying the rainbow flag, considered by the authorities as a ‘symbol of an extremist organisation’."]},{"k":"p","s":["Harassment, threats and acts of violence towards the LGBT+ community have increased."]},{"k":"p","s":["The North Caucasus republics are particularly intolerant of the LGBT+ community. There have been reports of the arrest, torture and killing of gay men in Chechnya, allegedly conducted by Chechen regional authorities."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Surrogacy"]},{"k":"p","s":["Russia has banned surrogacy for all foreign nationals except those married to Russian citizens. Read about ",["surrogacy arrangements in foreign countries","https://www.gov.uk/government/publications/surrogacy-overseas/surrogacy-overseas"],"."]},{"k":"hs","s":["Religious activities"]},{"k":"p","s":["Some religious activities are restricted, including preaching and distributing religious materials."]},{"k":"p","s":["Jehovah’s Witnesses are considered an extremist organisation in Russia. They can face harassment from authorities, including detention, particularly at places of worship."]},{"k":"p","s":["Some other minority religious groups, like Scientologists, also face discrimination."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you’re planning to drive in Russia, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s Russia guide","https://www.rac.co.uk/drive/travel/country/russia/"],"."]},{"k":"p","s":["You’ll need to have both the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["There are currently fuel shortages throughout Russia. In some places quotas may be imposed, including at short notice. If you intend to drive long distances, you should check fuel availability before travelling."]},{"k":"p","s":["If you have a residence permit or acquire Russian citizenship, you must get a Russian driving licence within one year. See ",["Living in Russia","https://www.gov.uk/guidance/living-in-russia#driving-in-russia"],"."]},{"k":"p","s":["Road safety in Russia is poor and road conditions are unpredictable. Take care when driving, take account of weather conditions and consider avoiding driving at night. Do not drive alone at night or sleep in your vehicle on the side of the road. Do not pick up hitchhikers."]},{"k":"p","s":["Traffic police often stop drivers for spot checks."]},{"k":"hs","s":["Bringing vehicles into Russia"]},{"k":"p","s":["If you plan to drive into Russia, you must declare your vehicle to the customs authority on entry. You can bring a vehicle into Russia without paying import taxes for up to one year."]},{"k":"p","s":["Green cards are no longer accepted as proof of car or road insurance. Check insurance requirements before entering."]},{"k":"p","s":["For questions about bringing a vehicle into Russia, contact the ",["Russian Embassy in the UK","https://london.mid.ru/en/"],"."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["Railway stations have airport-style security. Many railway services require passengers to show their passports on boarding."]},{"k":"p","s":["If you are travelling by overnight train, store valuables in the container under the bed or seat. Do not look after luggage for other travellers or let them store it in your compartment."]},{"k":"p","s":["Do not leave your sleeping compartment empty, as some compartments only have a simple lock on the sliding door. On some trains, there may be an extra security device attached to the fitted handle or lock. There may also be a steel switch at head-height on the door panel which, when pulled down, prevents the closed door from being opened."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["Air space will close during drone attacks. This has led to frequent and unpredictable delays, diversions and cancellations to flights in and out of Russian airports."]},{"k":"p","s":["There are restrictions on domestic flights to a number of airports in southern Russia, with disruption to internal flights to and from Moscow and other cities. Check the latest information with your airline or travel provider. Each airline regularly conducts their own safety and security risk assessments if they are flying over or near conflict regions. See ",["Air travel: safety and security","https://www.gov.uk/guidance/air-travel-safety-and-security"]]},{"k":"hs","s":["Air safety"]},{"k":"p","s":["The ",["UK Air Safety List","https://www.gov.uk/guidance/uk-air-safety-list"]," (ASL) lists all known airlines in Russia that do not meet international safety standards and are banned from operating commercial air services to, from, and within the UK. Check the UK Air Safety List when considering which airlines to fly with. The list is maintained by the Department for Transport, based on advice from the ",["UK Civil Aviation Authority","https://www.caa.co.uk/Commercial-Industry/Airlines/Licensing/Requirements-and-guidance/Third-Country-Operator-Certificates"],"."]},{"k":"hs","s":["Airline and railway sanctions"]},{"k":"p","s":["The UK government has sanctioned:"]},{"k":"li","s":["Aeroflot"]},{"k":"li","s":["Rossiya Airlines"]},{"k":"li","s":["Ural Airlines"]},{"k":"li","s":["Russian Railways"]},{"k":"p","s":["British nationals can buy flight tickets if the journey is starting in, or within, Russia without breaching UK sanctions. See more information from ",["the Office for Financial Sanctions Implementation (PDF)","https://assets.publishing.service.gov.uk/government/uploads/system/uploads/attachment_data/file/1136456/06.02.2023__Amended_Travel_General_Licence.pdf"],"."]},{"k":"p","s":["UK government staff do not travel on banned airlines. If staff need to travel internally, they may use airlines which also fly internationally to countries where international safety standards are maintained or on western manufactured aircraft."]},{"k":"hs","s":["Travellers with limited mobility"]},{"k":"p","s":["Wheelchair access can be limited in some public areas. Facilities for people with limited mobility vary. They can be poor or non-existent in some areas."]},{"k":"p","s":["See more advice on ",["disability and travelling abroad.","https://www.gov.uk/guidance/foreign-travel-for-disabled-people"]]},{"k":"h","s":["Natural disasters and extreme weather"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Earth tremors"]},{"k":"p","s":["Earth tremors are recorded throughout the year without consequences. The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Wild fires"]},{"k":"p","s":["There are areas of wildfires in western and southern Russia."]},{"k":"hs","s":["Arctic travel"]},{"k":"p","s":["Parts of Russia are in the Arctic Circle, including some very remote areas of land and sea. Emergency medical assistance and search and rescue are limited in these areas. See ",["Arctic travel safety advice","https://www.gov.uk/guidance/arctic-travel-safety-advice"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Russia","https://travelhealthpro.org.uk/country/186/russia#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Russia","https://travelhealthpro.org.uk/country/186/russia"],"."]},{"k":"p","s":["Altitude sickness is a risk in parts of Russia, including in the Western Caucasus mountains. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"hs","s":["HIV and AIDS"]},{"k":"p","s":["There is a higher rate of HIV and AIDS in Russia than in the UK. Take normal precautions to avoid exposure."]},{"k":"hs","s":["Air quality"]},{"k":"p","s":["Air quality can worsen in some weather conditions. Monitor local media and the regional websites for the ",["Ministry of Emergencies","https://en.mchs.gov.ru/"]," for more information."]},{"k":"hs","s":["Health examinations"]},{"k":"p","s":["If you’re in Russia for more than 90 days, you must have a regular comprehensive health examination. This applies to foreign nationals who are:"]},{"k":"li","s":["visiting"]},{"k":"li","s":["working"]},{"k":"li","s":["on highly qualified specialist visas"]},{"k":"li","s":["family members of any of the above, including children aged 6 and over"]},{"k":"p","s":["The examination includes tests for sexually transmitted infections and chest X-rays. You will have to submit fingerprints and other biometric data."]},{"k":"p","s":["If you are working or on a highly qualified specialist visa, you must complete the first health check within 30 days of arrival in Russia."]},{"k":"p","s":["If you’re visiting, or in any other category, you must complete the first health check within 90 days of arrival."]},{"k":"p","s":["Check with your employers and the Ministry of the Interior for the latest requirements."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["If your medication contains narcotic or psychoactive substances, you must carry a prescription in your name, translated into Russian, and notarised. Notarisation services are available in the UK from a notary public."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Russia"]},{"k":"p","s":["Russia does not have a reciprocal health agreement with the UK. European and Global Health Insurance Cards (EHIC and GHIC) are not valid in Russia. Any foreign national has a legal right to free medical care in life-threatening circumstances."]},{"k":"p","s":["Medical care may not meet western standards. Hospitals do not accept all health cases and may request payments before treatment."]},{"k":"p","s":["In remote areas, hospitals may not use disposable intravenous (IV) supplies, syringes and needles as standard practice. You may want to have your own supply."]},{"k":"p","s":["FCDO has a list of ",["medical providers in Russia","https://www.gov.uk/government/publications/russia-list-of-medical-facilitiespractitioners"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Russia"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Russia"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Russia"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Russia"]," in Russia"]},{"k":"li","s":["dealing with a ",["death in Russia","https://www.gov.uk/government/publications/russia-pereavement-packinformation"]]},{"k":"li","s":["being ",["arrested in Russia","https://www.gov.uk/government/publications/russia-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/russia/british-embassy-moscow"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/russia/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":42729,"change":"Updated information about drone attacks leading to short-notice restrictions on airspace use and airport operations (‘Warnings and insurance’ and ‘Safety and security’ pages)."}};
